/** 
 * Removes a number of occurrences of the specified element from this multiset. If the multiset contains fewer than this number of occurrences to begin with, all occurrences will be removed.
 * @param element the element whose occurrences should be removed
 * @param occurrences the number of occurrences of the element to remove
 * @return the count of the element before the operation; possibly zero
 * @throws IllegalArgumentException if {@code occurrences} is negative
 */
@Override public int remove(@Nullable Object element,int occurrences){
  if (occurrences == 0) {
    return count(element);
  }
  checkArgument(occurrences > 0,"Invalid occurrences: %s",occurrences);
  AtomicInteger existingCounter=safeGet(element);
  if (existingCounter == null) {
    return 0;
  }
  while (true) {
    int oldValue=existingCounter.get();
    if (oldValue != 0) {
      int newValue=Math.max(0,oldValue - occurrences);
      if (existingCounter.compareAndSet(oldValue,newValue)) {
        if (newValue == 0) {
          try {
            countMap.remove(element,existingCounter);
          } catch (UnsupportedOperationException | ClassCastException | NullPointerException e) {
            throw new RuntimeException("Failed to remove mapping from countMap", e);
          }
        }
        return oldValue;
      }
    }
 else {
      return 0;
    }
  }
}
